```python
#!/usr/bin/env python3
"""Generate a cleaned Liberty (.lib) file with power/ground (VDD/VSS) info removed.

Usage:
    python3 delete_pg.py <input.lib> <output.lib>

The script applies the following three rules in order:

1. Delete the whole block that starts with ``pg_pin (VDD) {`` and ends with the
   matching closing brace ``}`` (brace depth is tracked so nested braces are
   handled correctly).
2. Delete the whole block that starts with ``pg_pin (VSS) {`` and ends with the
   matching closing brace ``}``.
3. Delete every remaining line that contains the substring ``VDD`` or ``VSS``.

Only the Python standard library is used.
"""

import re
import sys

# Matches a line whose first non-whitespace text is exactly a pg_pin opening
# block for either VDD or VSS, e.g.:
#     pg_pin (VDD) {
#     pg_pin(VSS){
# Whitespace is allowed between the tokens.
_PG_PIN_START_RE = re.compile(r"^\s*pg_pin\s*\(\s*(VDD|VSS)\s*\)\s*\{")


def _brace_delta(line):
    """Return the net brace balance change represented by ``line``."""
    return line.count("{") - line.count("}")


def clean_lines(lines):
    """Return a new list of lines with the pg_pin(VDD/VSS) blocks and any
    VDD/VSS-containing lines removed."""
    result = []
    index = 0
    total = len(lines)
    block_depth = 0
    while index < total:
        line = lines[index]

        if block_depth > 0:
            # We are inside a pg_pin block; consume until it closes.
            block_depth += _brace_delta(line)
            index += 1
            continue

        if _PG_PIN_START_RE.match(line):
            # Start dropping the whole pg_pin block, brace matched.
            block_depth = _brace_delta(line)
            index += 1
            continue

        # Rule 3: drop any line still containing VDD or VSS.
        if "VDD" in line or "VSS" in line:
            index += 1
            continue

        result.append(line)
        index += 1
    return result


def main(argv):
    if len(argv) != 3:
        sys.stderr.write(
            "Usage: python3 delete_pg.py <input.lib> <output.lib>\n"
        )
        return 2

    input_path = argv[1]
    output_path = argv[2]

    with open(input_path, "r") as handle:
        lines = handle.readlines()

    cleaned = clean_lines(lines)

    with open(output_path, "w") as handle:
        handle.writelines(cleaned)

    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
```

